rules:
:root[data-theme="vivid"] {
  --heading-weight: 800;
  --radius: 14px;
}
[data-theme="vivid"] h1 { border-bottom: 0; padding-bottom: 0.15em; background-image: linear-gradient(90deg, var(--accent), var(--heading)); background-size: 64px 4px; background-repeat: no-repeat; background-position: left bottom; }
[data-theme="vivid"] h2 { border-bottom: 0; padding-bottom: 0; }
[data-theme="vivid"] h2::before { content: ""; display: inline-block; width: 0.5em; height: 0.5em; margin-right: 0.45em; border-radius: 50%; background: var(--accent); vertical-align: 0.12em; }
[data-theme="vivid"] blockquote { border-left: 0; padding: 0.6em 1em; background: var(--surface); border-radius: var(--radius); color: var(--fg); }
[data-theme="vivid"] hr { height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--accent), var(--heading), var(--link)); }
[data-theme="vivid"] th { background: var(--heading); color: var(--bg); border-color: var(--heading); }
[data-theme="vivid"] table { border-radius: var(--radius); }
[data-theme="vivid"] code:not(pre code) { color: var(--hl-keyword); }

variables:
:root[data-theme="vivid"] {
  --bg: #FFFDF8;
  --surface: #F3EEFF;
  --fg: #2D2A32;
  --muted: #6B6475;
  --border: #E6DCFB;
  --heading: #5B3BE0;
  --accent: #D5316B;
  --link: #087481;
  --quote: #FFB020;
  --hl-keyword: #B8246A;
  --hl-string: #07734F;
  --hl-comment: #70697C;
  --hl-number: #A44D06;
  --hl-function: #5B3BE0;
  --hl-type: #087481;
  --mm-node: #EFE9FF;
  --mm-border: #6C4BF4;
  --mm-text: #2D2A32;
  --mm-line: #E8457A;
  --mm-secondary: #E0F7F4;
  --mm-tertiary: #FFF1F6;
  --mm-note: #FFF1CC;
  --font-body: ui-rounded, "SF Pro Rounded", -apple-system, "PingFang TC", "PingFang SC", sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root[data-theme="vivid"] {
  --bg: #1A1625;
  --surface: #251F36;
  --fg: #F1ECFA;
  --muted: #AFA6BE;
  --border: #3A3150;
  --heading: #B69CFF;
  --accent: #FF7AA2;
  --link: #3DD6D0;
  --quote: #FFC857;
  --hl-keyword: #FF7AB8;
  --hl-string: #5BE3A8;
  --hl-comment: #948BA6;
  --hl-number: #FFA657;
  --hl-function: #B69CFF;
  --hl-type: #3DD6D0;
  --mm-node: #2E2548;
  --mm-border: #B69CFF;
  --mm-text: #F1ECFA;
  --mm-line: #FF7AA2;
  --mm-secondary: #1D3534;
  --mm-tertiary: #2A1F2E;
  --mm-note: #3D3420;
  }
}
